head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
// 세션정보를 얻기위한 함수사용

scwin.vScrenID = "ULDSTF20110.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_SetCode = function() {
    //  기간 from~ to  셋팅	
    edt_SDate.setValue('19000101');
    edt_EDate.setValue($c.ut.cGetToday("yyyymmdd")); // 현재날짜

    $c.stf.Combo_CBDataSetPeriod(cmb_PeriodTp);
};
scwin.fn_searchCode = function() {
    /*
	    00726 - 소속부유형코드
	    */
    var arrCid = [{
        cid: "SECT_TP_CD",
        cnm: "cmb_SECT_TP_CD"
    }];
    var objCod;
    var url = "/CodeAction.do?method=listCodeValueNameM&inputMessageId=CODE_M_IN&outputMessageId=CODE_M_OUT" + "&CD_ID_M='SECT_TP_CD'";
    dts_Cod.DataID = encodeURI(url);
    dts_Cod.reset();
    var strCbd = "",
        i, j;
    for (i = 0; i < arrCid.length; i++) {
        objCod = document.getElementById(arrCid[i].cnm);
        //alert('[objCod]'+objCod);
        if (objCod == null) {
            $c.win.alert(arrCid[i].cnm);
        }
        strCbd = "(null)^전체";
        for (j = 1; j <= dts_Cod.getTotalRow(); j++) {
            if (dts_Cod.getCellData(j, "CD_ENG_NM") == arrCid[i].cid) {
                strCbd = strCbd + (strCbd == "" ? "" : ",") + dts_Cod.getCellData(j, "VALUE") + "^" + dts_Cod.getCellData(j, "TEXT");
            }
        }
        objCod.CBData = strCbd;
    }
};
scwin.fn_list_sync = function() {
    var url = "/listingCommon.do";
    url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=listGeneral" + "&outputMessageId=LIST_CORPORATIONBOOK_ISUINST" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstsrch.select.newisurinst.condition" + "&{P}param01=" + $c.stf.getObjectValue(txb_ISUR_CD) + // 법인코드
        "&{P}param02=" + $c.stf.getObjectValue(txb_ISUR_CD) + // 법인코드
        "&{P}param03=" + $c.stf.getObjectValue(edt_SDate) + // 시작일자
        "&{P}param04=" + $c.stf.getObjectValue(edt_EDate) + // 종료일자
        "&{P}param05=" + $c.stf.getObjectValue(cmb_SECT_TP_CD) + // 소속부
        "&{P}param06=" + $c.stf.getObjectValue(cmb_SECT_TP_CD) + // 소속부
        "&{P}param07=" + $c.stf.getObjectValue(cmb_LIST_CLSS_CD) + // 신규상장
        "&{P}param08=" + $c.stf.getObjectValue(cmb_LIST_CLSS_CD) + "&{P}param09=" + $c.stf.getObjectValue(rdo_MARKET_TP_CD) + "&{P}param10=" + $c.stf.getObjectValue(rdo_MARKET_TP_CD);
    dts_List.DataID = encodeURI(url);
    dts_List.reset();
    $c.cm.ShowWin(grd_List);
};
scwin.img_COM_NM_onclick = function() {
    $c.cm.IsurcdSearch(txb_ISUR_CD, txb_COM_NM);
};
scwin.btn_Search_onclick = function() {
    if ($c.stf.getObjectValue(edt_SDate) == "") {
        $c.win.alert("[상장일 시작일자]을 입력세요.");
        edt_SDate.focus();
        return;
    }
    if ($c.stf.getObjectValue(edt_EDate) == "") {
        $c.win.alert("[상장일 종료일자]을 입력세요.");
        edt_EDate.focus();
        return;
    }
    if ($c.stf.compareFromToDate2(edt_SDate, edt_EDate)) {
        scwin.fn_list_sync();
    }
};
scwin.btn_Excel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07); // 엑셀
    //grd_List.GridToExcel("신규상장현황", "", "8");
    $c.data.downloadGridViewOffice(grd_List, "신규상장현황", "", 8, 0);
};
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    if (skw != "" && foColum == "1") {
        f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
        f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
        if (f1.indexOf(skw) != -1 || f2.indexOf(skw) != -1) return true;

        else return false;
    } else return true;
};
scwin.txb_ISUR_CD_onkeyup = function() {
    if (txb_ISUR_CD.getValue() == "") {
        Grd_com_isur.style.display = "none";
    } else {
        if (window.event.keyCode == 40) {
            //아래화살표눌렀을때 그리드로 포커스
            Grd_com_isur.focus();
        } else {
            $c.cm.fn_com_isur_nm(window.event.keyCode);
        }
    }
};
scwin.txb_ISUR_CD_onfocus = function() {
    Grd_com_isur.style.display = "none";
};
scwin.txb_ISUR_CD_onblur = function() {
    if (stFocusGrid == false) {
        Grd_com_isur.style.display = "none";
    }
    if (txb_ISUR_CD.getValue() == "") {
        txb_COM_NM.setValue("");
    }
};
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    if (kcode == '13') {
        $c.cm.fn_com_Confirm_set();
    }
};
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    $c.cm.fn_com_Confirm_set();
};
scwin.Grd_com_isur_OnClick = function(row, colid) {
    Grd_com_isur.style.display = "";
};
scwin.Grd_com_isur_OnSetFocus = function() {
    stFocusGrid = true;
};
scwin.Grd_com_isur_OnKillFocus = function() {
    stFocusGrid = false;
    Grd_com_isur.style.display = "none";
};
scwin.dts_List_OnLoadError = function() {
    $c.stf.alert_error(dts_List);
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    $c.cm.CloseWin(rowcount, grd_List);
};
scwin.btn_Close_onclick = function() {
    self.close();
};
scwin.btn_EDate_onclick = function() {
    popUpCalendar2(edt_EDate);
};
scwin.btn_SDate_onclick = function() {
    popUpCalendar2(edt_SDate);
};
scwin.cmb_PeriodTp_OnSelChange = function() {
    var vTp = $c.cp.valueOfIndex(cmb_PeriodTp, "VALUE", cmb_PeriodTp.getSelectedIndex());
    $c.stf.fn_setFromToDate(vTp, edt_SDate, edt_EDate);
};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_Top);
    if (js_market == "1" || js_market == "2") {
        $c.cm.setColumnProp(grd_List, "TR_MKT_NM", "Show", false);
        $c.stf.setObjectValue(rdo_MARKET_TP_CD, js_market);
        $c.stf.showObj(panel_mkt_gubun, false);
    } else {
        $c.stf.showObj(panel_mkt_gubun, true);
    }
    if (js_market == "1") {
        $c.stf.showObj(panel_SECT_TP_CD, false);
    }
    scwin.fn_SetCode();
    $c.elw.fn_searchCode();
    scwin.fn_list_sync();
    $c.cm.fn_com_isur(txb_ISUR_CD, txb_COM_NM);
};
